// Canonical Architecture Registry
const CANONICAL_REGISTRY = Object.freeze({
  PATHS: Object.freeze({
    UTILITY_TO_BUS: 'UTILITY_TO_BUS',
    PV_TO_INVERTER: 'PV_TO_INVERTER',
    BATTERY_TO_INVERTER: 'BATTERY_TO_INVERTER',
    INVERTER_TO_EPS: 'INVERTER_TO_EPS',
    GRID_BYPASS: 'GRID_BYPASS',
    ESSENTIAL_DISTRIBUTION: 'ESSENTIAL_DISTRIBUTION',
    NON_ESSENTIAL_DISTRIBUTION: 'NON_ESSENTIAL_DISTRIBUTION'
  }),
  EQUIPMENT: Object.freeze({
    UTILITY_METER: 'M0',
    MAIN_SWITCH: 'Q0',
    INVERTER_GRID_BREAKER: 'QG',
    INVERTER_EPS_BREAKER: 'QE',
    BYPASS_SWITCH: 'QBP',
    OUTGOING_BREAKER: 'QO',
    MANUAL_CHANGE_OVER: 'SBY',
    INVERTER: 'INV-1',
    BATTERY_BANK: 'BESS',
    PV_ARRAY_1: 'PV-1',
    PV_ARRAY_2: 'PV-2',
    ESSENTIAL_DB: 'DB-E',
    NON_ESSENTIAL_DB: 'DB-N'
  }),
  SWITCH_IDS: Object.freeze({
    M0: 'M0',
    Q0: 'Q0',
    QG: 'QG',
    QBP: 'QBP',
    QE: 'QE',
    QO: 'QO',
    SBY: 'SBY',
    QPV1: 'QPV1',
    QPV2: 'QPV2',
    QB: 'QB'
  }),
  ELECTRICAL_STATES: Object.freeze({
    ENERGIZED: 'ENERGIZED',
    DE_ENERGIZED: 'DE_ENERGIZED',
    ISOLATED: 'ISOLATED',
    FAULT: 'FAULT'
  })
});

// Electrical Connectivity Graph for Topological State Evaluation
class ElectricalConnectivityGraph {
  constructor() {
    this.nodes = new Map([
      ['utilityGrid', { id: 'utilityGrid', label: 'Utility Mains Grid', state: 'ENERGIZED' }],
      ['m0', { id: 'm0', label: 'Utility Revenue Meter (M0)', state: 'ENERGIZED' }],
      ['q0', { id: 'q0', label: 'Main Incomer Switch (Q0)', state: 'ENERGIZED' }],
      ['busG', { id: 'busG', label: 'Main AC Busbar (BUS-G)', state: 'ENERGIZED', voltage: 230 }],
      ['nonEssentialLoads', { id: 'nonEssentialLoads', label: 'Non-Essential Sub-Board', state: 'ENERGIZED' }],
      ['qg', { id: 'qg', label: 'Inverter Grid Port Breaker (QG)', state: 'CLOSED' }],
      ['inverter', { id: 'inverter', label: 'Hybrid Inverter 5kW/6kVA', state: 'ONLINE' }],
      ['qe', { id: 'qe', label: 'EPS Incomer Breaker (QE)', state: 'CLOSED' }],
      ['epsIncomer', { id: 'epsIncomer', label: 'EPS Incomer Node', state: 'ENERGIZED', voltage: 230 }],
      ['qbp', { id: 'qbp', label: 'Grid Bypass Breaker (QBP)', state: 'CLOSED' }],
      ['sby', { id: 'sby', label: 'Manual Changeover Switch (SBY I-0-II)', state: 'I' }],
      ['qo', { id: 'qo', label: 'Essential Board Outgoing MCB (QO)', state: 'CLOSED' }],
      ['essentialLoads', { id: 'essentialLoads', label: 'Essential Critical Loads Board', state: 'ENERGIZED', voltage: 230, source: 'Inverter EPS' }],
      ['pv1', { id: 'pv1', label: 'PV String 1 (MPPT1)', state: 'ENERGIZED' }],
      ['pv2', { id: 'pv2', label: 'PV String 2 (MPPT2)', state: 'ENERGIZED' }],
      ['battery', { id: 'battery', label: 'LiFePO4 51.2V BESS', state: 'CONNECTED' }]
    ]);
  }

  evaluate(inputs = {}) {
    const {
      utilityGrid = true,
      q0 = true,
      qg = true,
      qbp = true,
      qe = true,
      qo = true,
      sby = 'I',
      pv1 = true,
      pv2 = true,
      battery = true
    } = inputs;

    const busGEnergized = Boolean(utilityGrid && q0);
    const busG = {
      state: busGEnergized ? 'ENERGIZED' : 'DE_ENERGIZED',
      voltage: busGEnergized ? 230 : 0
    };

    const invHasAC = busGEnergized && qg;
    const invHasDC = pv1 || pv2 || battery;
    const invOperating = invHasAC || invHasDC;

    const epsIncomerEnergized = Boolean(invOperating && qe);
    const epsIncomer = {
      state: epsIncomerEnergized ? 'ENERGIZED' : 'DE_ENERGIZED',
      voltage: epsIncomerEnergized ? 230 : 0
    };

    const essentialLoads = {
      state: 'DE_ENERGIZED',
      voltage: 0,
      source: 'None'
    };

    if (qo && sby === 'I' && epsIncomerEnergized) {
      essentialLoads.state = 'ENERGIZED';
      essentialLoads.voltage = 230;
      essentialLoads.source = 'Inverter EPS';
    } else if (qo && sby === 'II' && busGEnergized && qbp) {
      essentialLoads.state = 'ENERGIZED';
      essentialLoads.voltage = 230;
      essentialLoads.source = 'Grid Bypass (QBP)';
    } else {
      essentialLoads.state = 'DE_ENERGIZED';
      essentialLoads.voltage = 0;
      essentialLoads.source = 'None';
    }

    return {
      busG,
      epsIncomer,
      essentialLoads
    };
  }
}

// Attach canonical registry and graph to PERSIAN_ELECTRICAL_DB
PERSIAN_ELECTRICAL_DB.registry = CANONICAL_REGISTRY;
PERSIAN_ELECTRICAL_DB.CANONICAL_REGISTRY = CANONICAL_REGISTRY;
PERSIAN_ELECTRICAL_DB.ElectricalConnectivityGraph = ElectricalConnectivityGraph;

if (typeof window !== "undefined") {
  window.PERSIAN_ELECTRICAL_DB = PERSIAN_ELECTRICAL_DB;
  window.CANONICAL_REGISTRY = CANONICAL_REGISTRY;
  window.ElectricalConnectivityGraph = ElectricalConnectivityGraph;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    PERSIAN_ELECTRICAL_DB,
    CANONICAL_REGISTRY,
    ElectricalConnectivityGraph
  };
}
